import React, { useState, useEffect, useRef } from 'react';
import { ethers } from 'ethers';
import './App.css';

const ENTRY_POINT = '0x5FF137D4b0FDCD49DcA30c7CF57E578a026d2789';
const PAYMASTER_ADDRESS = '0xe8b7C11ACA90B980C6c9E965114C8Be7e2A01d0c';
const ALSA_TOKEN = '0x253577D50896353c68773756Da7A150fA3e67035';
const RELAYER_URL = 'https://alsania-paymaster.netlify.app/.netlify/functions/relay';
const CHAIN_ID = 80002;

const TOKEN_ABI = [
  'function approve(address spender, uint256 amount) public returns (bool)',
  'function balanceOf(address account) public view returns (uint256)',
  'function decimals() public view returns (uint8)',
  'function transfer(address to, uint256 amount) public returns (bool)',
  'function allowance(address owner, address spender) public view returns (uint256)',
];

function computeUserOpHash(userOp, entryPoint, chainId) {
  const coder = ethers.AbiCoder.defaultAbiCoder();
  const packed = coder.encode(
    [
      'address',
      'uint256',
      'bytes32',
      'bytes32',
      'bytes32',
      'uint256',
      'bytes32',
      'bytes32',
      'bytes32'
    ],
    [
      userOp.sender,
      userOp.nonce,
      ethers.keccak256(userOp.initCode),
      ethers.keccak256(userOp.callData),
      userOp.accountGasLimits,
      userOp.preVerificationGas,
      userOp.gasFees,
      ethers.keccak256(userOp.paymasterAndData),
      ethers.keccak256(userOp.signature)
    ]
  );
  const hash = ethers.keccak256(packed);
  const finalPacked = coder.encode(
    ['bytes32', 'address', 'uint256'],
    [hash, entryPoint, Number(chainId)]
  );
  return ethers.keccak256(finalPacked);
}

function App() {
  const [signer, setSigner] = useState(null);
  const [address, setAddress] = useState('');
  const [balance, setBalance] = useState('0');
  const [isApproved, setIsApproved] = useState(false);
  const [multiplier, setMultiplier] = useState(1.00);
  const [isPlaying, setIsPlaying] = useState(false);
  const [gameResult, setGameResult] = useState(null);
  const [txHash, setTxHash] = useState('');
  const [loading, setLoading] = useState(false);
  const animationRef = useRef(null);

  const connectWallet = async () => {
    if (!window.ethereum) {
      alert('Please install MetaMask or any web3 wallet.');
      return;
    }
    try {
      const chainId = await window.ethereum.request({ method: 'eth_chainId' });
      if (chainId !== '0x13882') {
        try {
          await window.ethereum.request({
            method: 'wallet_switchEthereumChain',
            params: [{ chainId: '0x13882' }],
          });
        } catch (switchError) {
          if (switchError.code === 4902) {
            await window.ethereum.request({
              method: 'wallet_addEthereumChain',
              params: [{
                chainId: '0x13882',
                chainName: 'Polygon Amoy',
                nativeCurrency: { name: 'POL', symbol: 'POL', decimals: 18 },
                rpcUrls: ['https://polygon-amoy-bor-rpc.publicnode.com'],
                blockExplorerUrls: ['https://www.oklink.com/amoy'],
              }],
            });
          } else {
            throw new Error('Please switch to Polygon Amoy network.');
          }
        }
      }

      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner();
      const address = await signer.getAddress();
      setSigner(signer);
      setAddress(address);

      const token = new ethers.Contract(ALSA_TOKEN, TOKEN_ABI, provider);
      const bal = await token.balanceOf(address);
      const decimals = await token.decimals();
      setBalance(ethers.formatUnits(bal, decimals));

      const allowance = await token.allowance(address, PAYMASTER_ADDRESS);
      setIsApproved(allowance > 0n);
    } catch (error) {
      console.error(error);
      alert('Failed to connect: ' + error.message);
    }
  };

  const approvePaymaster = async () => {
    if (!window.ethereum) {
      alert('No wallet found.');
      return;
    }
    setLoading(true);
    try {
      const provider = new ethers.BrowserProvider(window.ethereum);
      const freshSigner = await provider.getSigner();
      const token = new ethers.Contract(ALSA_TOKEN, TOKEN_ABI, freshSigner);
      const tx = await token.approve(PAYMASTER_ADDRESS, ethers.parseUnits('10', 18));
      await tx.wait();
      setIsApproved(true);
      alert('✅ Paymaster approved!');
    } catch (error) {
      console.error(error);
      alert('❌ Approval failed: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const submitUserOp = async (userOp) => {
    const serializableUserOp = {
      sender: userOp.sender,
      nonce: userOp.nonce.toString(),
      initCode: userOp.initCode,
      callData: userOp.callData,
      accountGasLimits: userOp.accountGasLimits,
      preVerificationGas: userOp.preVerificationGas,
      gasFees: userOp.gasFees,
      paymasterAndData: userOp.paymasterAndData,
      signature: userOp.signature,
    };
    const response = await fetch(RELAYER_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userOp: serializableUserOp }),
    });
    const result = await response.json();
    if (!response.ok) throw new Error(result.error || 'Relayer error');
    return result;
  };

  const startGame = () => {
    if (!signer) return alert('Connect your wallet first!');
    if (!isApproved) return alert('Please approve the paymaster first!');
    setIsPlaying(true);
    setGameResult(null);
    setTxHash('');
    setMultiplier(1.00);
    const crashTarget = 1.5 + Math.random() * 8.5;
    let startTime = Date.now();
    const animate = () => {
      const elapsed = (Date.now() - startTime) / 1000;
      const currentMultiplier = Math.min(1.00 * Math.exp(0.2 * elapsed), crashTarget);
      setMultiplier(currentMultiplier);
      if (currentMultiplier >= crashTarget) {
        setGameResult({ type: 'crash', multiplier: currentMultiplier });
        setIsPlaying(false);
        return;
      }
      animationRef.current = requestAnimationFrame(animate);
    };
    animationRef.current = requestAnimationFrame(animate);
  };

  const cashOut = async () => {
    if (!isPlaying) return;
    setIsPlaying(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    const currentMultiplier = multiplier;
    setGameResult({ type: 'win', multiplier: currentMultiplier });
    setLoading(true);
    try {
      console.log('=== CASH OUT ===');
      
      // Get fresh provider and signer for the current wallet
      const provider = new ethers.BrowserProvider(window.ethereum);
      const freshSigner = await provider.getSigner();
      const currentAddress = await freshSigner.getAddress();
      console.log('Signer address:', currentAddress);

      const token = new ethers.Contract(ALSA_TOKEN, TOKEN_ABI, freshSigner);
      const winAmount = ethers.parseUnits((0.01 * currentMultiplier).toFixed(6), 18);
      console.log('Win:', ethers.formatUnits(winAmount, 18));
      const callData = token.interface.encodeFunctionData('transfer', [currentAddress, winAmount]);
      
      const entryPointContract = new ethers.Contract(
        ENTRY_POINT,
        ['function getNonce(address, uint192) view returns (uint256)'],
        freshSigner
      );
      const nonce = await entryPointContract.getNonce(currentAddress, 0);
      console.log('Nonce:', nonce.toString());
      
      const accountGasLimits = ethers.solidityPacked(['uint128', 'uint128'], [50000, 50000]);
      const gasFees = ethers.solidityPacked(['uint128', 'uint128'], [1000000000, 1000000000]);
      const paymasterAndData = ethers.solidityPacked(
        ['address', 'uint8', 'uint256'],
        [PAYMASTER_ADDRESS, 1, ethers.parseUnits('1', 18)]
      );
      
      const userOp = {
        sender: currentAddress,
        nonce: nonce,
        initCode: '0x',
        callData: callData,
        accountGasLimits: accountGasLimits,
        preVerificationGas: 50000,
        gasFees: gasFees,
        paymasterAndData: paymasterAndData,
        signature: '0x' + '1'.repeat(130),
      };
      
      const userOpHash = computeUserOpHash(userOp, ENTRY_POINT, CHAIN_ID);
      console.log('userOpHash:', userOpHash);
      
      const signature = await freshSigner.signMessage(ethers.getBytes(userOpHash));
      userOp.signature = signature;
      console.log('Signed!');
      
      const result = await submitUserOp(userOp);
      setTxHash(result.txHash);
      alert(`🎉 Won ${(0.01 * currentMultiplier).toFixed(4)} ALSA!`);
    } catch (error) {
      console.error('ERROR:', error);
      alert('❌ Transaction failed: ' + error.message);
      setGameResult({ type: 'error', message: error.message });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); };
  }, []);

  return (
    <div className="app">
      <header className="header">
        <h1>🐺 The Wolf's Gambit</h1>
        <p>Ride the multiplier. Cash out before the crash.</p>
      </header>
      <div className="wallet-section">
        {!address ? (
          <button className="btn btn-connect" onClick={connectWallet}>🦊 Connect Wallet</button>
        ) : (
          <div className="wallet-info">
            <span>🟢 {address.slice(0, 6)}...{address.slice(-4)}</span>
            <span>💰 {parseFloat(balance).toFixed(2)} ALSA</span>
            {!isApproved ? (
              <button className="btn btn-approve" onClick={approvePaymaster} disabled={loading}>
                {loading ? '⏳ Approving...' : '✅ Approve ALSA for Gas'}
              </button>
            ) : (
              <span className="badge-approved">✅ Gas approved</span>
            )}
          </div>
        )}
      </div>
      <div className="game-display">
        <div className="multiplier-container">
          <div className="multiplier-number">{multiplier.toFixed(2)}x</div>
          <div className="multiplier-bar">
            <div className="multiplier-fill" style={{ width: `${Math.min((multiplier / 10) * 100, 100)}%` }} />
          </div>
        </div>
        <div className="game-status">
          {gameResult?.type === 'crash' && <span className="status-crash">💥 CRASHED at {gameResult.multiplier.toFixed(2)}x</span>}
          {gameResult?.type === 'win' && <span className="status-win">🏆 CASHED OUT at {gameResult.multiplier.toFixed(2)}x</span>}
          {gameResult?.type === 'error' && <span className="status-error">❌ {gameResult.message}</span>}
          {!gameResult && isPlaying && <span className="status-playing">🎯 Riding...</span>}
          {!gameResult && !isPlaying && <span className="status-ready">Ready to play?</span>}
        </div>
      </div>
      <div className="controls">
        <button className="btn btn-cashout" onClick={cashOut} disabled={!isPlaying || loading}>
          {loading ? '⏳ Processing...' : '💰 Cash Out'}
        </button>
        <button className="btn btn-play" onClick={startGame} disabled={isPlaying || loading || !isApproved}>
          {isPlaying ? '🎯 Playing...' : '🚀 Start'}
        </button>
      </div>
      {txHash && (
        <div className="tx-result">
          ✅ Tx: <a href={`https://www.oklink.com/amoy/tx/${txHash}`} target="_blank" rel="noreferrer">{txHash.slice(0, 12)}...</a>
        </div>
      )}
      <footer className="footer">
        <p>💡 Gas paid in ALSA via Alsania Paymaster</p>
      </footer>
    </div>
  );
}

export default App;
